fn is_digit(c: Str) -> Bool {
  return c == "0" or c == "1" or c == "2" or c == "3" or c == "4" or c == "5" or c == "6" or c == "7" or c == "8" or c == "9"
}

fn unit_rank(c: Str) -> Int {
  if c == "d" {
    return 1
  }
  if c == "h" {
    return 2
  }
  if c == "m" {
    return 3
  }
  if c == "s" {
    return 4
  }
  return 0
}

fn unit_secs(rank: Int) -> Int {
  if rank == 1 {
    return 86400
  }
  if rank == 2 {
    return 3600
  }
  if rank == 3 {
    return 60
  }
  return 1
}

pub fn duration(s: Str) -> Result[Int, Str] {
  var total = 0
  var num = ""
  var last_rank = 0
  for c in s.chars() {
    if is_digit(c) {
      num = num + c
    } else {
      let rank = unit_rank(c)
      if rank == 0 or num == "" or rank <= last_rank {
        return Err("invalid duration")
      }
      total = total + num.to_int().unwrap_or(0) * unit_secs(rank)
      num = ""
      last_rank = rank
    }
  }
  if num != "" or last_rank == 0 {
    return Err("invalid duration")
  }
  return Ok(total)
}
